/**
 * Samhälle & institutioner → Utbildning & lärande → Universitet & högskola, 1611–1617 (0.33):
 * universities and faculties, courses and programmes, lectures and seminars, exams, degrees, the
 * degree project and study guidance. The pictures are built from a few recurring signs: a columned
 * main building with a mortarboard in the gable (the university), books and sheets (study and
 * texts), a lectern and a projection screen (lectures), a round table (seminars), year blocks and a
 * certificate with stars (degrees), three steps (the three levels), and a signpost (guidance).
 * Posed figures reach with real arms from the shoulder; a grey reference marks a contrast.
 */
import { C, all, arrow, circle, ellipse, g, line, path, rect, sparkle, star, type Svg } from './kit';
import { type Build } from './figures';
import { T } from './people';
import { P, greyed, type Mood } from './blindFix';

// ── Basics ───────────────────────────────────────────────────────────
const HL = C.accent;
const RED = '#e8302c';
const BLUE = '#5aa7e8';
const WALL = '#f3ecdf';
const STONE = '#eadfc6';
const COLS = ['#e85a5a', '#5aa7e8', '#7ac06a', '#f2c14e', '#c8a8d8', '#f28a2e'];
const f1 = (n: number) => n.toFixed(1);
const ground = line('M4 112 L116 112', C.grey2, 2);
const ring = (x: number, y: number, r: number, col: string = HL) => circle(x, y, r, 'none', col, 2.4);
const ok = (x: number, y: number, r = 8) => all(circle(x, y, r, C.green, C.ink, 1.2), path(`M${f1(x - r * 0.45)} ${y} L${f1(x - r * 0.1)} ${f1(y + r * 0.35)} L${f1(x + r * 0.5)} ${f1(y - r * 0.4)}`, 'none', C.white, r * 0.22));
const q = (x: number, y: number, sz = 14, col: string = C.navy) => T(x, y + sz * 0.36, '?', sz, col);
const ex = (x: number, y: number, sz = 14, col: string = RED) => T(x, y + sz * 0.36, '!', sz, col);
const tick = (x: number, y: number, s = 1, col: string = C.green) => line(`M${f1(x - 5 * s)} ${y} L${f1(x - 1.5 * s)} ${f1(y + 4 * s)} L${f1(x + 6 * s)} ${f1(y - 5 * s)}`, col, 2.4 * s);
const cross = (x: number, y: number, s = 1, col: string = RED) => line(`M${x - 6 * s} ${y - 6 * s} L${x + 6 * s} ${y + 6 * s} M${x + 6 * s} ${y - 6 * s} L${x - 6 * s} ${y + 6 * s}`, col, 2.6 * s);
const curve = (d: string, ex2: number, ey: number, ang: number, col: string = HL, w = 2) => all(line(d, col, w), g(`translate(${ex2} ${ey}) rotate(${ang})`, path('M0 0 L-6 -3.4 L-6 3.4 Z', col, null)));
const dashed = (d: string, col: string = C.grey, w = 1.6) => line(d, col, w, '4 3');

// ── Figures ──────────────────────────────────────────────────────────
type Pt = [number, number];
type Fig = Build & { mood?: Mood };
/** Head and shoulder positions of a standing figure at x with height factor h. */
const geo = (x: number, h = 1) => { const s = 0.84 * h, y0 = 112 - 49 * s; return { s, hy: y0 - 56 * s, hr: 10 * s, sy: y0 - 37 * s, sl: x - 12 * s, sr: x + 12 * s }; };
/** A figure (with mood face) whose arms are posed: `l`/`r` are canvas points (elbow …, hand). */
const F = (b: Fig, l?: Pt[], r?: Pt[]): Svg => {
  const x = b.x ?? 60, s = 0.84 * (b.h ?? 1), y0 = 112 - 49 * s;
  const col = b.grey ? C.grey : (b.top ?? C.sky), sk = b.grey ? C.grey2 : C.skin;
  const limb = (side: 1 | -1, pts: Pt[]) => {
    const sh: Pt = [x + side * 12 * s, y0 - 37 * s];
    const d = 'M' + [sh, ...pts].map(([a, c]) => `${f1(a)} ${f1(c)}`).join(' L');
    const h = pts[pts.length - 1]!;
    return all(g(`translate(${f1(x)} ${f1(y0)}) scale(${f1(side * s)} ${f1(s)})`, path('M14.9 -45 L25 -45 L25 4 L14.2 4 L14.2 -20 L14.9 -30 Z', C.paper, null)), line(d, C.ink, 7.4 * s), line(d, col, 4.8 * s), circle(h[0], h[1], 3.1 * s, sk, C.ink, 1.1));
  };
  return all(P(b), r ? limb(1, r) : '', l ? limb(-1, l) : '');
};
const fig = (x: number, top: string, mood: Mood = 'smile', more: Partial<Fig> = {}, l?: Pt[], r?: Pt[]) => F({ x, top, mood, ...more }, l, r);
/** Raise anything by dy (e.g. a figure standing on a step or a stage). */
const up = (dy: number, ...k: Svg[]) => g(`translate(0 ${-dy})`, ...k);
/** Glasses on the face of the standing figure at x. */
const glasses = (x: number, h = 1) => { const k = geo(x, h), r = k.hr * 0.3; return all(circle(x - k.hr * 0.36, k.hy, r, 'rgba(255,255,255,0.3)', C.ink, 1), circle(x + k.hr * 0.36, k.hy, r, 'rgba(255,255,255,0.3)', C.ink, 1), line(`M${f1(x - k.hr * 0.06)} ${f1(k.hy)} L${f1(x + k.hr * 0.06)} ${f1(k.hy)}`, C.ink, 0.9)); };
/** Head-and-shoulders seated figure (behind a table), facing us. */
const mini = (x: number, y: number, col: string, mood: 'smile' | 'frown' | 'flat' = 'smile', s = 1, long = false, hair: string = C.hair) => g(`translate(${x} ${y}) scale(${s})`, long ? path('M-8 -6 C-9 6 9 6 8 -6 Z', hair, null) : '', path('M-10 16 C-10 4 10 4 10 16 Z', col, C.ink, 1.4), circle(0, -6, 7.5, C.skin, C.ink, 1.4), path('M-7.5 -8 C-7.5 -16 7.5 -16 7.5 -8 C4 -11 -4 -11 -7.5 -8 Z', hair, null),
  circle(-2.6, -6, 1, C.ink, null), circle(2.6, -6, 1, C.ink, null),
  mood === 'smile' ? path('M-2.6 -2.6 Q0 -0.6 2.6 -2.6', 'none', C.ink, 1.1) : mood === 'flat' ? line('M-2.4 -2 L2.4 -2', C.ink, 1.1) : path('M-2.6 -1.4 Q0 -3.4 2.6 -1.4', 'none', C.ink, 1.1));
/** Head-and-shoulders seen from behind (a seated listener). */
const back = (x: number, y: number, col: string, hair: string = C.hair, long = false, s = 1) => g(`translate(${x} ${y}) scale(${s})`, path('M-13 22 C-13 8 13 8 13 22 Z', col, C.ink, 1.4), long ? path('M-9 8 C-10 -2 10 -2 9 8 Z', hair, C.ink, 1.2) : '', circle(0, 0, 8, hair, C.ink, 1.4));
/** A row of listeners seen from behind. */
const audience = (y: number, xs: number[], s = 1) => all(...xs.map((x, i) => back(x, y, COLS[(i + 1) % COLS.length]!, i % 3 === 1 ? '#7a4a2a' : C.hair, i % 2 === 0, s)));
/** Speech bubble centred on (cx, cy) whose tail points to (tx, ty). */
const say = (cx: number, cy: number, w: number, h: number, tx: number, ty: number, inner: Svg = '', fill: string = C.white) => {
  const L = cx - w / 2, R = cx + w / 2, Tp = cy - h / 2, B = cy + h / 2;
  let a: number[], b: number[];
  if (tx < L || tx > R) { const e = tx < L ? L : R, by = Math.max(Tp + 6, Math.min(B - 6, ty)); a = [e, by - 4.5]; b = [e, by + 4.5]; }
  else { const e = ty > cy ? B : Tp, bx = Math.max(L + 7, Math.min(R - 7, tx)); a = [bx - 5, e]; b = [bx + 5, e]; }
  return all(path(`M${a[0]} ${a[1]} L${tx} ${ty} L${b[0]} ${b[1]} Z`, fill, C.ink, 1.5), rect(L, Tp, w, h, fill, 6, C.ink, 1.5), path(`M${a[0]} ${a[1]} L${tx} ${ty} L${b[0]} ${b[1]} Z`, fill, null), inner);
};
/** Thought bubble with its small circles going down-left (side 1) or down-right (side −1) towards a head. */
const think = (cx: number, cy: number, w: number, h: number, side: 1 | -1, inner: Svg = '') => all(ellipse(cx, cy, w / 2, h / 2, C.white, C.ink, 1.5), circle(cx - side * (w / 4), cy + h / 2 + 4, 2.6, C.white, C.ink, 1.1), circle(cx - side * (w / 4 + 5), cy + h / 2 + 10, 1.8, C.white, C.ink, 1), inner);

// ── Things ───────────────────────────────────────────────────────────
/** Mortarboard (the academic sign). */
const cap = (x: number, y: number, s = 1, col: string = C.dark) => g(`translate(${x} ${y}) scale(${s})`, path('M-8 1 L-8 8 C-4 11 4 11 8 8 L8 1', col, C.ink, 1.2), path('M-15 0 L0 -6 L15 0 L0 6 Z', col, C.ink, 1.2), line('M0 0 L11 3 L11 10', C.gold, 1.4), circle(11, 11, 1.8, C.gold, null));
/** The university main building: steps, columns and a gable with a mortarboard; base on y. */
const building = (x: number, base: number, s = 1, col: string = STONE, withCap = true) => g(`translate(${x} ${base}) scale(${s})`, rect(-34, -6, 68, 6, '#d9cdb2', 1, C.ink, 1.4), rect(-30, -44, 60, 38, col, 1, C.ink, 1.6), rect(-6, -22, 12, 16, '#7a4a2a', 1, C.ink, 1.2), ...[-23, -12, 12, 23].map((cx) => rect(cx - 3, -40, 6, 34, C.white, 1, C.ink, 1.1)), rect(-33, -49, 66, 6, '#d9cdb2', 1, C.ink, 1.4), path('M-35 -49 L0 -66 L35 -49 Z', col, C.ink, 1.6), withCap ? cap(0, -55, 0.55) : '');
/** A plain modern block with windows (another building on campus, a company, a home). */
const block = (x: number, base: number, w: number, h: number, col: string = '#cfd8e2', rows = 2) => all(rect(x - w / 2, base - h, w, h, col, 2, C.ink, 1.5), ...Array.from({ length: rows }, (_, r) => all(...Array.from({ length: Math.max(1, Math.floor(w / 12)) }, (_, c) => rect(x - w / 2 + 4 + c * 12, base - h + 5 + r * 12, 7, 7, '#bfe3f5', 1, C.ink, 0.9)))));
const tree = (x: number, base: number, s = 1) => g(`translate(${x} ${base}) scale(${s})`, rect(-2, -14, 4, 14, C.brown, 1, C.ink, 1), circle(0, -20, 10, '#6fae5a', C.ink, 1.3));
/** A company: a building with a gear on the front. */
const company = (x: number, base: number, s = 1) => g(`translate(${x} ${base}) scale(${s})`, rect(-20, -44, 40, 44, '#9ab0c4', 2, C.ink, 1.5), ...[0, 1, 2].map((r) => all(rect(-15, -38 + r * 11, 8, 6, '#bfe3f5', 1, C.ink, 0.8), rect(7, -38 + r * 11, 8, 6, '#bfe3f5', 1, C.ink, 0.8))), gearS(0, -24, 5), rect(-5, -10, 10, 10, '#5a6a7a', 1, C.ink, 1));
const gearS = (x: number, y: number, r: number, col = '#e0b23c') => g(`translate(${x} ${y})`, ...Array.from({ length: 8 }, (_, i) => { const a = (i / 8) * Math.PI * 2; return rect(+f1(Math.cos(a) * r * 1.1 - r * 0.22), +f1(Math.sin(a) * r * 1.1 - r * 0.22), r * 0.44, r * 0.44, col, 1, C.ink, 0.8); }), circle(0, 0, r, col, C.ink, 1.1), circle(0, 0, r * 0.4, C.paper, C.ink, 0.9));
/** Closed book seen from the front. */
const bookC = (x: number, y: number, s = 1, col: string = BLUE) => g(`translate(${x} ${y}) scale(${s})`, rect(-10, -13, 20, 26, col, 2, C.ink, 1.3), line('M-6 -13 L-6 13', 'rgba(0,0,0,0.25)', 1.4), rect(-3, -8, 10, 5, 'rgba(255,255,255,0.75)', 1, null));
/** Open book. */
const openBook = (x: number, y: number, s = 1, col: string = BLUE) => g(`translate(${x} ${y}) scale(${s})`, path('M-16 9 C-12 7 -6 7 0 10 C6 7 12 7 16 9 L16 12 C12 10 6 10 0 13 C-6 10 -12 10 -16 12 Z', col, C.ink, 1.1), path('M0 -6 C-6 -9 -12 -9 -16 -7 L-16 9 C-12 7 -6 7 0 10 C6 7 12 7 16 9 L16 -7 C12 -9 6 -9 0 -6 Z', C.white, C.ink, 1.4), line('M0 -6 L0 10', C.ink, 1.1), line('M-13 -3 L-4 -2 M-13 1 L-4 2 M-13 5 L-4 6 M4 -2 L13 -3 M4 2 L13 1 M4 6 L13 5', C.grey, 1));
const tome = (x: number, y: number, w: number, h: number, col: string) => all(rect(x, y, w, h, col, 1.5, C.ink, 1.3), line(`M${x + 3} ${y + 2} L${x + 3} ${y + h - 2}`, 'rgba(255,255,255,0.6)', 1.2));
/** A pile of n books lying on y. */
const pile = (x: number, y: number, n: number, w = 26, th = 6.4) => all(...Array.from({ length: n }, (_, i) => tome(x - w / 2 + (i % 2) * 2, y - (i + 1) * (th + 0.6), w, th, COLS[i % COLS.length]!)));
/** A sheet with n text lines. */
const sheet = (x: number, y: number, w: number, h: number, n = 4, col: string = C.white) => all(rect(x, y, w, h, col, 2, C.ink, 1.4), ...Array.from({ length: n }, (_, i) => line(`M${x + 5} ${f1(y + 8 + i * ((h - 14) / Math.max(1, n - 1)))} L${x + w - 5} ${f1(y + 8 + i * ((h - 14) / Math.max(1, n - 1)))}`, '#9aa3ad', 1.4)));
/** An exam sheet: numbered questions with answer lines. */
const exam = (x: number, y: number, s = 1, mark: Svg = '') => g(`translate(${x} ${y}) scale(${s})`, rect(-18, -24, 36, 48, C.white, 2, C.ink, 1.5), ...[0, 1, 2].map((i) => all(T(-12, -11 + i * 14, String(i + 1), 7, C.navy), line(`M-7 ${-13 + i * 14} L13 ${-13 + i * 14} M-7 ${-8 + i * 14} L9 ${-8 + i * 14}`, '#9aa3ad', 1.2))), mark);
const pencil = (x: number, y: number, rot = 0, s = 1, col: string = C.yellow) => g(`translate(${x} ${y}) rotate(${rot}) scale(${s})`, rect(-3, -24, 6, 20, col, 1, C.ink, 1.2), rect(-3, -27, 6, 4, '#f2a0c0', 1, C.ink, 1), path('M-3 -4 L0 3 L3 -4 Z', '#f0d8b0', C.ink, 1), path('M-1 0.6 L0 3 L1 0.6 Z', C.ink, null));
const redPen = (x: number, y: number, rot = 0, s = 1) => pencil(x, y, rot, s, RED);
/** Certificate with a red seal; `inner` sits in its upper half. */
const cert = (x: number, y: number, s = 1, inner: Svg = '') => g(`translate(${x} ${y}) scale(${s})`, rect(-18, -22, 36, 44, '#fbf6e6', 2, C.ink, 1.5), rect(-15, -19, 30, 38, 'none', 1, '#c9a24a', 1), line('M-10 2 L10 2 M-10 7 L6 7', '#9aa3ad', 1.2), path('M6 12 L4 21 L8 18 L11 21 L10 12 Z', RED, C.ink, 0.8), circle(8, 12, 5, RED, C.ink, 1), circle(8, 12, 2.6, 'none', '#ffd0c0', 0.8), inner);
/** A row of stars inside a certificate. */
const stars = (n: number, y = -9) => all(...Array.from({ length: n }, (_, i) => star((i - (n - 1) / 2) * 9, y, 4.2, C.gold)));
/** Projection screen; `inner` is drawn on it. */
const screen = (x: number, y: number, w: number, h: number, inner: Svg = '') => all(rect(x - w / 2 - 2, y - h / 2 - 4, w + 4, 4, C.dark, 1, C.ink, 1), rect(x - w / 2, y - h / 2, w, h, C.white, 1, C.ink, 1.5), inner);
/** A bar chart (the content of a slide or a report). */
const bars = (x: number, y: number, s = 1) => g(`translate(${x} ${y}) scale(${s})`, line('M-12 8 L12 8', C.ink, 1.2), rect(-10, -2, 5, 10, BLUE, 1, null), rect(-3, -8, 5, 16, C.orange, 1, null), rect(4, -4, 5, 12, C.green, 1, null));
const lectern = (x: number, base = 112, s = 1, col: string = C.brown) => g(`translate(${x} ${base}) scale(${s})`, path('M-9 0 L-7 -30 L7 -30 L9 0 Z', col, C.ink, 1.5), path('M-12 -30 L12 -30 L10 -36 L-10 -36 Z', '#7a4a2a', C.ink, 1.3), line('M3 -36 L7 -46', C.ink, 1.4), circle(7.5, -47, 2, C.dark, null));
const clock = (x: number, y: number, r = 9, hh = 10, mm = 2) => { const a = (hh % 12) / 12 * Math.PI * 2, b = mm / 12 * Math.PI * 2; return all(circle(x, y, r, C.white, C.ink, 1.6), line(`M${x} ${y} L${f1(x + Math.sin(a) * r * 0.5)} ${f1(y - Math.cos(a) * r * 0.5)}`, C.ink, 1.6), line(`M${x} ${y} L${f1(x + Math.sin(b) * r * 0.8)} ${f1(y - Math.cos(b) * r * 0.8)}`, C.ink, 1.2)); };
const laptop = (x: number, y: number, s = 1, inner: Svg = '') => g(`translate(${x} ${y}) scale(${s})`, rect(-16, -22, 32, 21, C.dark, 2, C.ink, 1.4), rect(-14, -20, 28, 17, '#bfe3f5', 1, null), inner, path('M-20 -1 L20 -1 L22 3 L-22 3 Z', '#9aa3ad', C.ink, 1.3));
const flask = (x: number, y: number, s = 1, col: string = C.green) => g(`translate(${x} ${y}) scale(${s})`, path('M-3 -12 L3 -12 L3 -4 L10 8 C11 11 9 12 7 12 L-7 12 C-9 12 -11 11 -10 8 L-3 -4 Z', 'rgba(220,240,252,0.7)', C.ink, 1.3), path('M-7.5 4 L7.5 4 L10 8 C11 11 9 12 7 12 L-7 12 C-9 12 -11 11 -10 8 Z', col, null), line('M-4 -12 L4 -12', C.ink, 1.6));
const globe = (x: number, y: number, r: number) => all(circle(x, y, r, '#bfe3f5', C.ink, 1.4), path(`M${f1(x - r * 0.6)} ${f1(y - r * 0.4)} C${f1(x - r * 0.2)} ${f1(y - r * 0.7)} ${f1(x + r * 0.1)} ${f1(y - r * 0.1)} ${f1(x - r * 0.3)} ${f1(y + r * 0.2)} C${f1(x - r * 0.6)} ${f1(y + r * 0.3)} ${f1(x - r * 0.7)} ${f1(y)} ${f1(x - r * 0.6)} ${f1(y - r * 0.4)} Z M${f1(x + r * 0.2)} ${f1(y + r * 0.1)} C${f1(x + r * 0.6)} ${f1(y - r * 0.2)} ${f1(x + r * 0.8)} ${f1(y + r * 0.3)} ${f1(x + r * 0.4)} ${f1(y + r * 0.7)} C${f1(x + r * 0.2)} ${f1(y + r * 0.5)} ${f1(x + r * 0.1)} ${f1(y + r * 0.3)} ${f1(x + r * 0.2)} ${f1(y + r * 0.1)} Z`, '#7ac06a', C.ink, 0.8));
/** Small calendar page; `inner` in the middle. */
const cal = (x: number, y: number, s = 1, inner: Svg = '', head: string = RED) => g(`translate(${x} ${y}) scale(${s})`, rect(-14, -14, 28, 28, C.white, 3, C.ink, 1.4), rect(-14, -14, 28, 8, head, 3, C.ink, 1.4), line('M-7 -17 L-7 -11 M7 -17 L7 -11', C.ink, 1.6), inner);
const sun = (x: number, y: number, r = 7) => all(...Array.from({ length: 8 }, (_, i) => { const a = (i / 8) * Math.PI * 2; return line(`M${f1(x + Math.cos(a) * (r + 3))} ${f1(y + Math.sin(a) * (r + 3))} L${f1(x + Math.cos(a) * (r + 7))} ${f1(y + Math.sin(a) * (r + 7))}`, C.gold, 2); }), circle(x, y, r, C.yellow, C.ink, 1.4));
const leaf = (x: number, y: number, s = 1, col: string = C.orange) => g(`translate(${x} ${y}) scale(${s})`, path('M0 8 C-8 2 -6 -8 0 -10 C6 -8 8 2 0 8 Z', col, C.ink, 1.1), line('M0 8 L0 -8', C.ink, 0.8));
const flake = (x: number, y: number, s = 1) => g(`translate(${x} ${y}) scale(${s})`, line('M0 -8 L0 8 M-7 -4 L7 4 M-7 4 L7 -4', '#5aa7d6', 1.8));
const heart = (x: number, y: number, s = 1, fill: string = C.red) => g(`translate(${x} ${y}) scale(${s})`, path('M0 8 C-12 0 -10 -10 -4 -10 C-1 -10 0 -8 0 -6 C0 -8 1 -10 4 -10 C10 -10 12 0 0 8 Z', fill, C.ink, 1.2));
const cup = (x: number, y: number, col: string = C.white) => g(`translate(${x} ${y})`, path('M-6 -6 L6 -6 L5 6 C5 8 -5 8 -5 6 Z', col, C.ink, 1.3), path('M6 -3 C10 -3 10 3 5 3', 'none', C.ink, 1.3));
const phone = (x: number, y: number, s = 1, inner: Svg = '') => g(`translate(${x} ${y}) scale(${s})`, rect(-9, -16, 18, 32, C.dark, 3, C.ink, 1.5), rect(-7, -12, 14, 22, '#bfe3f5', 1, null), inner);
const envelope = (x: number, y: number, s = 1) => g(`translate(${x} ${y}) scale(${s})`, rect(-16, -11, 32, 22, C.white, 2, C.ink, 1.6), path('M-16 -11 L0 3 L16 -11', 'none', C.ink, 1.4));
const table = (x1: number, x2: number, y: number, col: string = C.tan) => all(rect(x1, y, x2 - x1, 6, col, 2, C.ink, 1.5), line(`M${x1 + 5} ${y + 6} L${x1 + 5} 112 M${x2 - 5} ${y + 6} L${x2 - 5} 112`, C.brown, 2.4));
const chair = (x: number, base = 112, col: string = '#7a8a9a') => all(rect(x - 8, base - 34, 3, 34, col, 1, C.ink, 1), rect(x - 8, base - 16, 16, 3, col, 1, C.ink, 1), line(`M${x + 6} ${base - 13} L${x + 6} ${base}`, col, 2.4));
const window = (x: number, y: number, w = 26, h = 22) => all(rect(x - w / 2, y - h / 2, w, h, '#cfe9f7', 2, C.ink, 1.5), line(`M${x} ${y - h / 2} L${x} ${y + h / 2} M${x - w / 2} ${y} L${x + w / 2} ${y}`, C.ink, 1.2));
